/* gcode.js — генератор управляющих программ для GRBL */

const GCodeGen = (function () {
  'use strict';

  // формат числа: убираем лишние нули, точность 3 знака
  function fmt(n) {
    return Number(n.toFixed(3));
  }

  // шапка и подвал программы
  function header(spindle, safeZ) {
    return [
      '(Generated by CNCGen)',
      '(GRBL postprocessor)',
      'G21 ; mm',
      'G90 ; absolute',
      'G17 ; XY plane',
      'M3 S' + spindle + ' ; spindle on',
      'G0 Z' + fmt(safeZ) + ' ; safe Z',
      ''
    ].join('\n');
  }

  function footer(safeZ) {
    return [
      '',
      'G0 Z' + fmt(safeZ) + ' ; retract',
      'M5 ; spindle off',
      'M30 ; program end'
    ].join('\n');
  }

  // ================= ПЛОСКОСТЬ =================
  function generatePlane(params) {
    const {
      length, width, depth, stepover, origin, zigzag,
      toolDiameter, spindle, feed, plungeFeed, stepdown, safeZ
    } = params;

    let code = header(spindle, safeZ);
    code += '(Geometry: plane ' + length + 'x' + width + ' mm, depth ' + depth + ' mm)\n';
    code += '(Tool: D' + toolDiameter + ' mm)\n\n';

    const tool_r = toolDiameter / 2;
    const step_y = toolDiameter * (stepover / 100);
    const passes = Math.ceil(depth / stepdown);

    // начало координат
    let x0 = 0, y0 = 0;
    if (origin === 'center') {
      x0 = -length / 2;
      y0 = -width / 2;
    }

    // границы рабочей зоны с компенсацией радиуса инструмента
    const x_start = x0 + tool_r;
    const x_end = x0 + length - tool_r;
    const y_start = y0 + tool_r;
    const y_end = y0 + width - tool_r;

    let current_z = 0;
    let y_pos = y_start;
    let reverse = false;

    for (let pass = 1; pass <= passes; pass++) {
      const z_target = -Math.min(pass * stepdown, depth);
      code += '(Pass ' + pass + ' / ' + passes + ', Z=' + fmt(z_target) + ')\n';

      // первая строчка: позиционирование + врезание
      code += 'G0 X' + fmt(x_start) + ' Y' + fmt(y_pos) + '\n';
      code += 'G1 Z' + fmt(z_target) + ' F' + plungeFeed + '\n';
      code += 'G1 X' + fmt(x_end) + ' F' + feed + '\n';

      current_z = z_target;
      y_pos += step_y;
      reverse = !reverse;

      // остальные строчки
      while (y_pos <= y_end) {
        code += 'G1 Y' + fmt(y_pos) + '\n';

        if (zigzag && reverse) {
          code += 'G1 X' + fmt(x_start) + '\n';
        } else {
          code += 'G1 X' + fmt(x_end) + '\n';
        }

        y_pos += step_y;
        reverse = !reverse;
      }

      // поднять инструмент после прохода
      code += 'G0 Z' + fmt(safeZ) + '\n';
      y_pos = y_start;
      reverse = false;
    }

    code += footer(safeZ);
    return code;
  }

  // ================= ОТВЕРСТИЕ =================
  function generateHole(params) {
    const {
      diameter, depth,
      toolDiameter, spindle, feed, plungeFeed, stepdown, safeZ
    } = params;

    let code = header(spindle, safeZ);
    code += '(Geometry: hole D' + diameter + ' mm, depth ' + depth + ' mm)\n';
    code += '(Tool: D' + toolDiameter + ' mm)\n';
    code += '(Strategy: helical interpolation)\n\n';

    const tool_r = toolDiameter / 2;
    const hole_r = diameter / 2;
    const cut_r = hole_r - tool_r;

    if (cut_r <= 0) {
      code += '(ERROR: tool diameter >= hole diameter)\n';
      code += footer(safeZ);
      return code;
    }

    const passes = Math.ceil(depth / stepdown);
    const z_step = depth / passes;

    // начальная позиция — центр (X0 Y0)
    code += 'G0 X0 Y0\n';
    code += 'G0 Z' + fmt(safeZ) + '\n';

    for (let pass = 1; pass <= passes; pass++) {
      const z_target = -pass * z_step;
      code += '(Pass ' + pass + ' / ' + passes + ', Z=' + fmt(z_target) + ')\n';

      // подвод на радиус по X
      code += 'G0 X' + fmt(cut_r) + ' Y0\n';

      // врезание по винтовой линии (G2 — по часовой, полный оборот)
      code += 'G2 X' + fmt(cut_r) + ' Y0 Z' + fmt(z_target) + ' I' + fmt(-cut_r) + ' J0 F' + plungeFeed + '\n';

      // дополнительный круг на глубине для чистоты
      code += 'G2 X' + fmt(cut_r) + ' Y0 I' + fmt(-cut_r) + ' J0 F' + feed + '\n';

      // возврат в центр
      code += 'G1 X0 Y0\n';
    }

    code += footer(safeZ);
    return code;
  }

  // ================= РЕЗЬБА =================
  function generateThread(params) {
    const {
      diameter, pitch, depth, kind, hand,
      toolDiameter, spindle, feed, plungeFeed, safeZ
    } = params;

    let code = header(spindle, safeZ);
    code += '(Geometry: thread ' + (kind === 'internal' ? 'internal' : 'external') + ')\n';
    code += '(Diameter: ' + diameter + ' mm, pitch: ' + pitch + ' mm, depth: ' + depth + ' mm)\n';
    code += '(Hand: ' + (hand === 'left' ? 'left' : 'right') + ')\n';
    code += '(Tool: thread mill D' + toolDiameter + ' mm)\n\n';

    const tool_r = toolDiameter / 2;
    let cut_r;

    if (kind === 'internal') {
      // внутренняя резьба — инструмент внутри отверстия
      cut_r = diameter / 2 - tool_r;
    } else {
      // наружная резьба — инструмент снаружи
      cut_r = diameter / 2 + tool_r;
    }

    if (cut_r <= 0) {
      code += '(ERROR: invalid geometry for given tool diameter)\n';
      code += footer(safeZ);
      return code;
    }

    const turns = Math.ceil(depth / pitch);
    const z_per_turn = -pitch;

    code += '(Turns: ' + turns + ')\n\n';

    // начало — центр X0 Y0
    code += 'G0 X0 Y0 Z' + fmt(safeZ) + '\n';
    code += 'G0 X' + fmt(cut_r) + ' Y0\n';
    code += 'G1 Z0 F' + plungeFeed + '\n';

    let z_current = 0;

    for (let turn = 1; turn <= turns; turn++) {
      const z_next = z_current + z_per_turn;
      code += '(Turn ' + turn + ' / ' + turns + ')\n';

      // G2 (CW) для правой резьбы внутренней или левой наружной
      // G3 (CCW) для левой резьбы внутренней или правой наружной
      let arc_cmd = 'G2';
      if ((kind === 'internal' && hand === 'left') || (kind === 'external' && hand === 'right')) {
        arc_cmd = 'G3';
      }

      code += arc_cmd + ' X' + fmt(cut_r) + ' Y0 Z' + fmt(z_next) +
        ' I' + fmt(-cut_r) + ' J0 F' + feed + '\n';

      z_current = z_next;
    }

    // выход по спирали на безопасную высоту
    code += 'G1 Z' + fmt(safeZ) + ' F' + plungeFeed + '\n';
    code += 'G1 X0 Y0\n';

    code += footer(safeZ);
    return code;
  }

  // ================= ГЛАВНАЯ ФУНКЦИЯ =================
  return function generate(type, params) {
    if (type === 'plane') return generatePlane(params);
    if (type === 'hole') return generateHole(params);
    if (type === 'thread') return generateThread(params);
    return '(Unknown geometry type)';
  };
})();